"""Where to go to prove a skill: a hand-curated map, never generated by the model.

Every URL here was opened and checked by hand (see README). Skills are matched by
alias, so "Postgres", "PostgreSQL" and "psql" all land on the same entry.
"""

import re

HR = "https://www.hackerrank.com/skills-verification/"
EX = "https://exercism.org/tracks/"

# (aliases, [(platform, what you get, url)])
CATALOG = [
    (["python"], [
        ("HackerRank", "Python (Basic) skill certificate", HR + "python_basic"),
        ("Exercism", "Python track with mentor feedback", EX + "python"),
    ]),
    (["javascript", "js", "node", "node.js", "nodejs"], [
        ("HackerRank", "JavaScript (Basic) skill certificate", HR + "javascript_basic"),
        ("Exercism", "JavaScript track", EX + "javascript"),
    ]),
    (["typescript", "ts"], [("Exercism", "TypeScript track", EX + "typescript")]),
    (["java"], [
        ("HackerRank", "Java (Basic) skill certificate", HR + "java_basic"),
        ("Exercism", "Java track", EX + "java"),
    ]),
    (["c++", "cpp"], [("Exercism", "C++ track", EX + "cpp")]),
    (["c#", "csharp", ".net", "dotnet"], [
        ("HackerRank", "C# (Basic) skill certificate", HR + "csharp_basic"),
        ("Exercism", "C# track", EX + "csharp"),
    ]),
    (["go", "golang"], [
        ("HackerRank", "Go (Basic) skill certificate", HR + "go_basic"),
        ("Exercism", "Go track", EX + "go"),
    ]),
    (["rust"], [("Exercism", "Rust track", EX + "rust")]),
    (["sql", "mysql", "postgresql", "postgres", "sqlite", "t-sql", "pl/sql"], [
        ("HackerRank", "SQL (Basic) skill certificate", HR + "sql_basic"),
        ("HackerRank", "SQL (Intermediate) skill certificate", HR + "sql_intermediate"),
        ("LeetCode", "Top SQL 50 study plan", "https://leetcode.com/studyplan/top-sql-50/"),
    ]),
    (["react", "react.js", "reactjs"], [
        ("HackerRank", "React (Basic) skill certificate", HR + "react_basic"),
    ]),
    (["angular"], [("HackerRank", "Angular (Basic) skill certificate", HR + "angular_basic")]),
    (["data structures", "algorithms", "dsa", "problem solving", "competitive programming"], [
        ("HackerRank", "Problem Solving (Basic) skill certificate", HR + "problem_solving_basic"),
        ("LeetCode", "Problem set", "https://leetcode.com/problemset/"),
        ("Codeforces", "Rated contests", "https://codeforces.com/contests"),
    ]),
    (["aws", "amazon web services", "ec2", "s3", "lambda"], [
        ("AWS", "AWS Certification", "https://aws.amazon.com/certification/"),
    ]),
    (["azure", "microsoft azure"], [
        ("Microsoft Learn", "Microsoft Credentials", "https://learn.microsoft.com/en-us/credentials/"),
    ]),
    (["gcp", "google cloud", "google cloud platform", "bigquery"], [
        ("Google Cloud", "Google Cloud certification", "https://cloud.google.com/learn/certification"),
    ]),
    (["kubernetes", "k8s"], [
        ("Linux Foundation", "CKAD: Certified Kubernetes Application Developer",
         "https://training.linuxfoundation.org/certification/certified-kubernetes-application-developer-ckad/"),
    ]),
    (["linux", "bash", "shell"], [
        ("Linux Foundation", "LFCS: Linux Foundation Certified Sysadmin",
         "https://training.linuxfoundation.org/certification/linux-foundation-certified-sysadmin-lfcs/"),
    ]),
    (["terraform"], [
        ("HashiCorp", "Terraform Associate certification",
         "https://developer.hashicorp.com/certifications"),
    ]),
    (["git", "github", "version control"], [
        ("Learn Git Branching", "Interactive Git levels", "https://learngitbranching.js.org/"),
    ]),
    (["machine learning", "ml", "scikit-learn", "sklearn", "deep learning", "pytorch",
      "tensorflow", "keras", "pandas", "data science", "computer vision", "nlp"], [
        ("Kaggle", "Kaggle Learn courses with certificates", "https://www.kaggle.com/learn"),
        ("Kaggle", "Competitions", "https://www.kaggle.com/competitions"),
    ]),
]

GENERAL = [
    ("Exercism", "70+ language tracks", "https://exercism.org/tracks"),
    ("HackerRank", "All skill certifications", "https://www.hackerrank.com/skills-verification"),
]

_INDEX = {alias: tests for aliases, tests in CATALOG for alias in aliases}


def _key(name):
    return re.sub(r"\s+", " ", name.strip().lower())


def tests_for(skill_name):
    return [{"platform": p, "title": t, "url": u} for p, t, u in _INDEX.get(_key(skill_name), [])]


def training_plan(skills):
    """External tests for each scored skill that has any, weakest claims first."""
    plan, used = [], set()
    for skill in sorted(skills, key=lambda s: s["score"]):
        tests = [t for t in tests_for(skill["name"]) if t["url"] not in used]
        if tests:
            used.update(t["url"] for t in tests)
            plan.append({"skill": skill["name"], "score": skill["score"], "level": skill["level"], "tests": tests})
    general = [{"platform": p, "title": t, "url": u} for p, t, u in GENERAL]
    return {"by_skill": plan, "general": general}


def all_urls():
    return sorted({u for _, tests in CATALOG for *_, u in tests} | {u for *_, u in GENERAL})
